\title{The Jacobi-Signed Circle Count:\\ Escaping the Residue Dial, Pinned at the Weil Floor}
\author{Aristotle}
\date{13 August 2026}

\begin{document}
\maketitle

\begin{abstract}
For an odd modulus $N$ let $S(N)=\{(x,y)\in(\Z/N\Z)^2 : x^2+y^2=1\}$ be the unit circle over $\Z/N\Z$, and define the \emph{Jacobi-signed circle count}
\[
W(N) \;=\; \sum_{(x,y)\in S(N)} \jac{x}{N},
\]
where $\jac{\cdot}{N}$ is the Jacobi symbol. We establish the complete structure theory of this statistic and use it to settle its viability as an arithmetic witness for the factorisation of semiprimes.

We prove: (i) a \emph{collapse identity}, $W(p)=\sum_x \chi(x(1-x^2))$ for prime $p$ with $\chi$ the Legendre character---the two-dimensional circle count is a one-dimensional cubic character sum, equal up to sign to the trace of Frobenius of $y^2=x-x^3$; (ii) \emph{multiplicativity}, $W(mn)=W(m)W(n)$ for coprime $m,n$, hence $W(pq)=W(p)W(q)$; (iii) \emph{vanishing}, $W(p)=0$ whenever $p\equiv 3 \pmod 4$, so $W$ annihilates a density-$3/4$ family of semiprimes; (iv) \emph{exact parity}, $W(p)\equiv 2 \pmod 4$ for $p\equiv 1\pmod 4$; (v) an \emph{exact second moment} $\sum_d A(d)^2 = 2p(p-1)$ over the quadratic twists $A(d)=\sum_x\chi(x^3-dx)$, from which the \emph{Weil bound} $W(p)^2\le 4p$ follows by pure averaging, with no input from algebraic geometry; (vi) the \emph{Jacobsthal identity} $A(1)^2+A(\nu)^2=4p$ for any nonresidue $\nu$, which exhibits the Weil bound as the shadow of an exact conservation law and yields Fermat's two-square theorem with explicit character-sum witnesses: $p=(W(p)/2)^2+(A(\nu)/2)^2$ with $W(p)/2$ odd.

We further prove, by exact evaluation, that $W$ is \emph{not a residue dial}: no function of $p \bmod 8$ (nor of $p \bmod 4$) reproduces $W(p)$, and no function of $N \bmod 8$ reproduces $W(N)$. The verdict is nonetheless negative: the statistic costs $\Theta(N)$ to evaluate, factors as a symmetric product in which $p$ and $q$ are inseparable, and lives in a window of width $O(\sqrt N)$ inside a search space of size $N$. We formulate the resulting principle: summing away one circle coordinate turns any character-weighted circle count into a Jacobi sum, and Jacobi sums have absolute value exactly $\sqrt p$---the square-root floor is a property of the circle, not of the weight.
\end{abstract}

\section{Introduction}

\subsection{Witnesses, dials, and floors}

A recurring temptation in computational number theory is to look for an \emph{arithmetic witness}: a quantity $F(N)$, defined by a natural formula, whose value leaks information about the prime factorisation of $N$. The temptation is well founded---the class number, the order of the multiplicative group, the number of points on a curve mod $N$ all \emph{are} functions of the factorisation. The difficulty is that in almost every case the witness is either (a) as expensive as factoring itself, (b) a function of publicly available data, or (c) drowned in noise.

Case (b) deserves a name. Call $F$ a \emph{residue dial} modulo $m$ if there is a function $f$ with $F(N)=f(N \bmod m)$ for all admissible $N$. A dial is worthless: its value is computable from $N$ alone in constant time. Several natural point-count witnesses collapse to dials. The plain count of the circle $x^2+y^2=1$ over $\Z/N\Z$ satisfies $|S(p)|=p-\chi(-1)$, which for $N=pq$ gives $(p-\varepsilon_p)(q-\varepsilon_q)$ with $\varepsilon\in\{\pm1\}$ determined by residues mod $4$; counts attached to binary quadratic forms and to Gaussian sums behave similarly.

This paper studies a witness designed specifically to break the dial: weight each circle point by the Jacobi symbol of its $x$-coordinate. The weighting destroys the crude leading term and, as we prove, genuinely escapes the dial. What remains is a study of how a \emph{different} obstruction---the square-root cancellation floor for character sums---takes over the moment the first obstruction is removed.

\subsection{The statistic}

Throughout, $N$ is odd and $\jac{a}{N}$ denotes the Jacobi symbol, the completely multiplicative extension in the lower argument of the Legendre symbol. For prime $p$, $\jac{a}{p}=\chi_p(a)$ is the quadratic character: $+1$ if $a$ is a nonzero square, $-1$ if a nonsquare, $0$ if $p\mid a$.

\begin{definition}[Jacobi-signed circle count]
For odd $N\ge 3$ set
\[
S(N)=\{(x,y)\in(\Z/N\Z)^2 : x^2+y^2=1\},\qquad
W(N)=\sum_{(x,y)\in S(N)}\jac{x}{N}.
\]
\end{definition}

\begin{definition}[Cubic sum form]
For odd $N$ set $\widetilde W(N)=\sum_{x\in\Z/N\Z}\jac{x(1-x^2)}{N}$.
\end{definition}

Theorem~\ref{thm:collapse} identifies $W$ and $\widetilde W$ for prime moduli, and Theorem~\ref{thm:geommult} does so for arbitrary odd moduli; we use $W$ for both.

\section{The collapse identity and elementary symmetries}

Fix an odd prime $p$ and write $\chi=\chi_p$, extended by $\chi(0)=0$. Two facts are used constantly:
\begin{itemize}
\item[(C1)] $\sum_{x \bmod p}\chi(x)=0$;
\item[(C2)] $\#\{y : y^2=a\}=\chi(a)+1$ for every $a$.
\end{itemize}

\begin{theorem}[Collapse to a cubic character sum]\label{thm:collapse}
For every odd prime $p$,
\[
W(p)=\sum_{x \bmod p}\chi\bigl(x(1-x^2)\bigr).
\]
\end{theorem}

\begin{proof}
Group by $x$. For fixed $x$ the inner sum is $\chi(x)$ times $\#\{y: y^2=1-x^2\}=\chi(1-x^2)+1$ by (C2). Hence
$W(p)=\sum_x\chi(x)(\chi(1-x^2)+1)=\sum_x\chi(x(1-x^2))+\sum_x\chi(x)$, and the last sum vanishes by (C1).
\end{proof}

The polynomial $x(1-x^2)=-(x^3-x)$ has three distinct roots $0,\pm1$; the right-hand side is therefore, up to the sign $\chi(-1)$, minus the trace of Frobenius of $y^2=x^3-x$. This is the structural reason the Weil bound appears below.

\begin{theorem}[Reflection]\label{thm:refl}
$W(p)=\chi(-1)W(p)$.
\end{theorem}

\begin{proof}
The substitution $x\mapsto -x$ is a bijection and replaces $x(1-x^2)$ by $-x(1-x^2)$.
\end{proof}

\begin{corollary}[Vanishing on the supersingular half]\label{cor:vanish}
If $p\equiv 3\pmod 4$ then $W(p)=0$.
\end{corollary}

\begin{proof}
Then $\chi(-1)=-1$, so $W(p)=-W(p)$ by Theorem~\ref{thm:refl}.
\end{proof}

\begin{lemma}[Reflection-parity]\label{lem:half}
Let $f:\Z/p\Z\to\Z$ satisfy $f(-x)=f(x)$ and $f(0)=0$, and let $H=\{x\ne 0 : 2\overline x<p\}$ be the ``lower half'' of the nonzero classes, where $\overline x\in\{0,\dots,p-1\}$. Then $\sum_x f(x)=2\sum_{x\in H}f(x)$, and $|H|=(p-1)/2$.
\end{lemma}

\begin{proof}
$x\mapsto -x$ is a fixed-point-free involution of the nonzero classes ($p$ odd) exchanging $H$ with its complement, since $\overline{-x}=p-\overline x$ and $2\overline x=p$ is impossible. As $f$ is invariant and kills $0$, the halves contribute equally.
\end{proof}

\begin{theorem}[Parity]\label{thm:even}
For every odd prime $p$, $W(p)$ is even.
\end{theorem}

\begin{proof}
For $p\equiv 3\pmod 4$ use Corollary~\ref{cor:vanish}. For $p\equiv 1 \pmod 4$, $\chi(-1)=1$, so $f(x)=\chi(x(1-x^2))$ is even under $x\mapsto -x$ and $f(0)=0$; apply Lemma~\ref{lem:half}.
\end{proof}

\section{Multiplicativity: the factors become inseparable}

\begin{lemma}[Multiplicativity in the numerator]
For odd $N$ and $x,y\in\Z/N\Z$, writing $\jmath_N(x)=\jac{\overline x}{N}$, we have $\jmath_N(xy)=\jmath_N(x)\jmath_N(y)$.
\end{lemma}

\begin{lemma}[Splitting along the modulus]\label{lem:split}
If $N=mn$ with $m,n$ odd, then $\jmath_N(x)=\jmath_m(x \bmod m)\,\jmath_n(x\bmod n)$.
\end{lemma}

Both are immediate from the definition of the Jacobi symbol as completely multiplicative in each argument and dependent only on the numerator modulo the denominator.

\begin{theorem}[Multiplicativity of the cubic sum]\label{thm:mult}
If $m,n$ are odd and coprime then $\widetilde W(mn)=\widetilde W(m)\widetilde W(n)$.
\end{theorem}

\begin{proof}
Let $u=x\bmod m$, $v=x \bmod n$. Applying Lemma~\ref{lem:split} to $x(1-x^2)$ and using that reduction is a ring homomorphism gives
$\jmath_{mn}(x(1-x^2))=\jmath_m(u(1-u^2))\jmath_n(v(1-v^2))$. By the Chinese Remainder Theorem, $x\mapsto(u,v)$ is a bijection; reindex and factor the double sum.
\end{proof}

\begin{theorem}[Multiplicativity of the geometric weight]\label{thm:geommult}
If $m,n$ are odd and coprime then $W(mn)=W(m)W(n)$.
\end{theorem}

\begin{proof}
Under the CRT bijection $(\Z/mn\Z)^2\cong(\Z/m\Z)^2\times(\Z/n\Z)^2$, a pair $(x,y)$ lies on the circle iff both reductions do (necessity by applying the ring maps, sufficiency by injectivity). Lemma~\ref{lem:split} splits the weight, so the summand factors and the sum factors.
\end{proof}

\begin{corollary}[Semiprime product formula]\label{cor:semi}
For distinct odd primes $p\ne q$, $\;W(pq)=W(p)W(q)$.
\end{corollary}

\begin{corollary}[A density-$3/4$ blind spot]\label{cor:blind}
If $p\equiv 3\pmod 4$ or $q\equiv3\pmod4$ then $W(pq)=0$. In particular $W(3q)=0$ for every prime $q\ne 3$, and $W(15)=W(21)=0$, so $W$ is not injective on semiprimes.
\end{corollary}

Corollary~\ref{cor:semi} is the crux of the negative result. The statistic \emph{is} factor-dependent, unlike a dial; but the dependence is through a \emph{symmetric product}, so recovering $W(p)$ and $W(q)$ from $W(N)$ is itself a factoring problem, and even then each of $W(p),W(q)$ determines only one leg of a two-square decomposition (Theorem~\ref{thm:twosq}).

\section{The Weil floor by second moments}

\begin{definition}[Twist sums]
For $d\in\Z/p\Z$ set $A(d)=\sum_{x}\chi(x^3-dx)$, so $-A(d)$ is the trace of Frobenius of $y^2=x^3-dx$.
\end{definition}

\begin{lemma}\label{lem:WA}
If $p\equiv1\pmod4$ then $W(p)=A(1)$.
\end{lemma}

\begin{proof}
$x(1-x^2)=(-1)(x^3-x)$ and $\chi(-1)=1$.
\end{proof}

\begin{lemma}[Basic quadratic character sums]\label{lem:basic}
\begin{enumerate}
\item $\sum_u \chi(u^2-u)=-1$.
\item For $a,b\in\Z/p\Z$, $\sum_d \chi((d-a)(d-b))=p-1$ if $a=b$, and $-1$ otherwise.
\end{enumerate}
\end{lemma}

\begin{proof}
(1) Drop $u=0$; for $u\ne0$, $u^2-u=u^2(1-u^{-1})$, so $\chi(u^2-u)=\chi(1-u^{-1})$. The map $u\mapsto 1-u^{-1}$ is a bijection from the nonzero classes onto $\Z/p\Z\setminus\{1\}$ with inverse $v\mapsto(1-v)^{-1}$, so the sum is $\sum_{v\ne1}\chi(v)=-\chi(1)=-1$ by (C1).
(2) If $a=b$ the summand is $\chi((d-a)^2)$, equal to $1$ for $d\ne a$ and $0$ at $d=a$. If $a\ne b$, put $d=a+(b-a)u$; then $(d-a)(d-b)=(b-a)^2(u^2-u)$ and $\chi((b-a)^2)=1$, reducing to (1).
\end{proof}

\begin{lemma}[Square scaling]\label{lem:scale}
For $c\ne0$ and any $e$, $A(c^2e)=\chi(c)A(e)$; in particular $A(c^2)^2=A(1)^2$. Also $A(0)=0$.
\end{lemma}

\begin{proof}
Substitute $x=cu$: $(cu)^3-c^2e(cu)=c^3(u^3-eu)$ and $\chi(c^3)=\chi(c)$. For $d=0$, $A(0)=\sum_x\chi(x^3)=\sum_x\chi(x)=0$.
\end{proof}

\begin{lemma}[Diagonal inner sum]\label{lem:diag}
For $p\equiv 1\pmod 4$ and each $x$, $\sum_{y : y^2=x^2}\chi(xy)$ equals $0$ if $x=0$ and $2$ otherwise.
\end{lemma}

\begin{proof}
For $x\ne0$ the solutions are $y=\pm x$, distinct as $p$ is odd, and $\chi(x^2)=1$, $\chi(-x^2)=\chi(-1)=1$.
\end{proof}

\begin{theorem}[Exact second moment]\label{thm:moment}
For $p\equiv1\pmod4$, $\displaystyle\sum_{d\bmod p}A(d)^2=2p(p-1)$.
\end{theorem}

\begin{proof}
Using $\chi(x^3-dx)\chi(y^3-dy)=\chi(xy)\chi((x^2-d)(y^2-d))$ and swapping the order of summation,
\[
\sum_d A(d)^2=\sum_x\sum_y\chi(xy)\sum_d\chi\bigl((d-x^2)(d-y^2)\bigr).
\]
By Lemma~\ref{lem:basic}(2) the inner sum equals $p\,[x^2=y^2]-1$, so
\[
\sum_d A(d)^2 = p\sum_x\sum_{y:y^2=x^2}\chi(xy)-\Bigl(\sum_x\chi(x)\Bigr)^2.
\]
The second term vanishes by (C1); the first is $p\cdot2(p-1)$ by Lemma~\ref{lem:diag}.
\end{proof}

\begin{theorem}[Weil bound, elementary proof]\label{thm:weil}
For every odd prime $p$, $W(p)^2\le 4p$, i.e.\ $|W(p)|\le 2\sqrt p$.
\end{theorem}

\begin{proof}
For $p\equiv3\pmod4$ the left side is $0$. Let $p\equiv1\pmod4$ and put $F(d)=A(d)^2\ge0$. By Lemma~\ref{lem:scale}, $F(c^2)=A(1)^2$ for $c\ne0$, so $\sum_{c\ne0}F(c^2)=(p-1)A(1)^2$. Since $c\mapsto c^2$ is at most $2$-to-$1$ and $F\ge0$,
$\sum_{c\ne0}F(c^2)\le 2\sum_d F(d)=4p(p-1)$ by Theorem~\ref{thm:moment}. Cancel $p-1>0$ and use Lemma~\ref{lem:WA}.
\end{proof}

\begin{corollary}[The semiprime Weil floor]\label{cor:floor}
For distinct odd primes and $N=pq$, $W(N)^2\le 16N$, i.e.\ $|W(N)|\le 4\sqrt N$.
\end{corollary}

\section{The Weil floor is an identity: Jacobsthal and two squares}

\begin{lemma}[Pushforward along squaring]\label{lem:push}
For any $F:\Z/p\Z\to\Z$, $\;\sum_c F(c^2)=\sum_d(\chi(d)+1)F(d)$.
\end{lemma}

\begin{proof}
By (C2) the fibre of $c\mapsto c^2$ over $d$ has $\chi(d)+1$ elements.
\end{proof}

\begin{theorem}[Jacobsthal identity]\label{thm:jac}
Let $p\equiv 1\pmod 4$ and let $\nu$ be a quadratic nonresidue. Then $A(1)^2+A(\nu)^2=4p$.
\end{theorem}

\begin{proof}
Let $F(d)=A(d)^2$, so $F(0)=0$. By Lemma~\ref{lem:scale}, $F(c^2)=A(1)^2$ and $F(\nu c^2)=A(\nu)^2$ for $c\ne0$, whence
\[
\sum_c F(c^2)=(p-1)A(1)^2,\qquad \sum_c F(\nu c^2)=(p-1)A(\nu)^2 .
\]
Lemma~\ref{lem:push} gives $\sum_c F(c^2)=\sum_d(\chi(d)+1)F(d)$. Applying it to $d\mapsto F(\nu d)$ and substituting $d\mapsto\nu^{-1}d$, using $\chi(\nu)=-1$, gives $\sum_c F(\nu c^2)=\sum_d(1-\chi(d))F(d)$. Adding, the character weights cancel:
\[
(p-1)\bigl(A(1)^2+A(\nu)^2\bigr)=2\sum_d F(d)=4p(p-1)
\]
by Theorem~\ref{thm:moment}. Cancel $p-1$.
\end{proof}

\begin{lemma}[Evenness of all twists]\label{lem:Aeven}
For $p\equiv1\pmod4$ and any $d$, $A(d)$ is even.
\end{lemma}

\begin{proof}
$f(x)=\chi(x^3-dx)$ satisfies $f(-x)=\chi(-1)f(x)=f(x)$ and $f(0)=0$; apply Lemma~\ref{lem:half}.
\end{proof}

\begin{theorem}[Fermat's two-square theorem with explicit witnesses]\label{thm:twosq}
Let $p\equiv1\pmod4$ and $\nu$ a nonresidue. Put $a=W(p)/2$ and $b=A(\nu)/2$, integers by Theorem~\ref{thm:even} and Lemma~\ref{lem:Aeven}. Then $p=a^2+b^2$.
\end{theorem}

\begin{proof}
Divide Theorem~\ref{thm:jac} by $4$, using $W(p)=A(1)$.
\end{proof}

