"""
Algorithm 1: linear-time evaluation of the Jacobi-signed circle count.

W(N) = sum over circle points (x, y) of (x/N)  collapses, by summing y away, to
the one-dimensional cubic character sum  W(N) = sum_x ( x(1 - x^2) / N ).
That reduces the cost from O(N^2) to O(N log N) bit operations.
"""

from __future__ import annotations

from typing import Iterator


def jacobi(a: int, n: int) -> int:
    """Jacobi symbol (a/n) for odd n >= 1, in O(log n) steps."""
    if n <= 0 or n % 2 == 0:
        raise ValueError("lower argument must be odd and positive")
    a %= n
    result = 1
    while a != 0:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a %= n
    return result if n == 1 else 0


def circle_weight_quadratic(n: int) -> int:
    """Reference implementation straight from the definition. Cost O(n^2 log n)."""
    total = 0
    for x in range(n):
        jx = jacobi(x, n)
        if jx:
            for y in range(n):
                if (x * x + y * y) % n == 1 % n:
                    total += jx
    return total


def circle_weight(n: int) -> int:
    """W(n) via the collapse identity. Cost O(n log n) bit operations."""
    if n % 2 == 0:
        raise ValueError("modulus must be odd")
    total = 0
    for x in range(n):
        total += jacobi(x * (1 - x * x) % n, n)
    return total


def circle_weight_stream(n: int) -> Iterator[int]:
    """Running partial sums of W(n): useful for watching the cancellation."""
    total = 0
    for x in range(n):
        total += jacobi(x * (1 - x * x) % n, n)
        yield total


if __name__ == "__main__":
    for n in (5, 13, 17, 21, 41, 85, 173):
        fast, slow = circle_weight(n), circle_weight_quadratic(n)
        print(f"N = {n:>4}   W(N) = {fast:>5}   (definition agrees: {fast == slow})")

