INPUT : prime p with p = 1 (mod 4)
OUTPUT: certificate {second moment, Weil bound, Jacobsthal identity, two squares}

// Step 1: Legendre table by Euler's criterion            O(p log p)
for a <- 0 to p-1:  chi[a] <- 0 if a = 0 else (+1 if a^((p-1)/2) = 1 mod p else -1)

// Step 2: all quadratic twist sums                       O(p^2)
for x <- 0 to p-1:  cube[x] <- x^3 mod p
for d <- 0 to p-1:
    A[d] <- sum over x of chi[(cube[x] - d*x) mod p]

// Step 3: certify the exact second moment
M <- sum over d of A[d]^2
assert M = 2*p*(p-1)

// Step 4: certify the Weil bound
assert A[1]^2 <= 4*p
        // derivation: A[c^2] = chi(c) A[1] gives (p-1) A[1]^2 <= 2 M = 4p(p-1)

// Step 5: certify the conservation law and read off two squares
nu <- least v >= 2 with chi[v] = -1
assert A[1]^2 + A[nu]^2 = 4*p
a <- A[1] / 2 ;  b <- A[nu] / 2
assert a^2 + b^2 = p  and  a is odd
return (A[1], A[nu], M, a, b)

INPUT : sample size S, prime cap P, permutation count T, RNG seed
OUTPUT: for each covariate, (observed |r|, null 95th percentile, empirical p-value)

// Step 1: admissible pool and statistic table
pool  <- { primes p < P : p = 1 (mod 4) }        // else F vanishes identically
for p in pool: Ftab[p] <- F(p)                    // O(P) each via the collapse identity

// Step 2: sample distinct unordered semiprime factorisations
sample <- {} 
while |sample| < S:  draw {p, q} uniformly from pool, p != q; add if new

// Step 3: the statistic vector, by multiplicativity
for (p, q) in sample:  stat[(p,q)] <- Ftab[p] * Ftab[q]

// Step 4: observed correlations
for each covariate g in {p, q, p+q, |p-q|, log N}:
    cov <- [ g(p,q) for (p,q) in sample ]
    r_obs <- |PEARSON(stat, cov)|

    // Step 5: permutation null -- preserves both marginals, destroys association
    nulls <- []
    repeat T times:
        shuffle stat into stat'
        append |PEARSON(stat', cov)| to nulls
    sort nulls
    threshold <- nulls[ floor(0.95 T) ]
    pvalue    <- #{ v in nulls : v >= r_obs } / T
    report (r_obs, threshold, pvalue, LEAK if r_obs >= threshold else NO EVIDENCE)
